#define RES vec2(400.0, 225.0)

const float PERIODE = 33.1797;
const float VMARCHE = 48.0;
const float VECHELLE = 26.0;
const float VROULE = 56.0;
const float XD = 384.0;
const float XG = 16.0;
const float XLANCER = 74.0;
const float XGOUFFRE = 28.0;
const float T1 = (XD - XLANCER) / VROULE;
const float T2 = T1 + 0.5;
const float T3 = T2 + (XD - XG) / VROULE;
const float T4 = T3 + 0.5;
const float T5 = T4 + (XD - XG) / VROULE;
const float T6 = T5 + 0.5;
const float T7 = T6 + (XD - XGOUFFRE) / VROULE;
const vec2 SINGE = vec2(48.0, 165.0);
const float X0 = 52.0;
const float XL1 = 350.0;
const float XL2 = 58.0;
const float XL3 = 340.0;
const float XFIN = 296.0;
const float XCOEUR = 268.0;
const float T0 = 0.8;
const float TA1 = 7.0083;
const float TA2 = 8.6465;
const float TB1 = 14.7298;
const float TB2 = 16.6043;
const float TC1 = 22.4793;
const float TC2 = 25.7630;
const float DEBUT_VICTOIRE = 26.6797;
const float HAUT_SAUT = 14.0;
const float DUREE_SAUT = 0.55;
const int NB = 6;
const int NS = 4;
const int NC = 3;
const float DEPARTS[NB] = float[NB](2.4500, 6.9500, 10.4500, 13.9500, 17.9500, 23.7000);
const float MORTS[NB] = float[NB](99.0000, 10.7220, 24.7977, 99.0000, 21.3377, 99.0000);
const float SAUTS[NS] = float[NS](4.0760, 9.1560, 19.6760, 21.5600);
const float COUPS[NC] = float[NC](1.9680, 6.0080, 17.5720);

vec4 gTonneau[NB];
vec4 gDebris[NB];
vec4 gHeros;
float gSaut;
float gSt;
float gSp;
float gLance;
float gSecousse;
float gTemps;
float gTt;

float alea(float n){ return fract(sin(n * 91.3458) * 47453.5453); }

bool bx(vec2 l, float x0, float y0, float x1, float y1)
{
    return l.x >= x0 && l.x <= x1 && l.y >= y0 && l.y <= y1;
}

float distSegment(vec2 p, vec2 a, vec2 b)
{
    vec2 pa = p - a, ba = b - a;
    float h = clamp(dot(pa, ba)/dot(ba, ba), 0., 1.);
    return length(pa - ba*h);
}

float niv0(float x){ return 8.0 + 0.008 * (x - 12.0); }
float niv1(float x){ return 56.0 - 0.008 * (x - 12.0); }
float niv2(float x){ return 104.0 + 0.008 * (x - 12.0); }
float niv3(float x){ return 152.0; }
float niv4(float x){ return 192.0; }

vec4 pixelHeros(vec2 l, float fr, float enAir, float st, float sp, float clin)
{
    vec4 c = vec4(0.);
    float rebond = (enAir < .5 && (fr == 1. || fr == 3.)) ? 1. : 0.;
    vec2 u = vec2(l.x, l.y - rebond);
    float gardeVisible = (st < .5 || (st < 1.5 && sp < .12) || (st > 4.5 && sp > .88)) ? 1. : 0.;

    if(distSegment(u, vec2(-4., 5.), vec2(-11., 1.)) < .8) c = vec4(.35, .22, .14, 1.);
    if(length(u - vec2(-11., 1.)) < 1.) c = vec4(.90, .70, .30, 1.);
    if(gardeVisible > .5){
        if(bx(u, -4., 6., -4., 7.)) c = vec4(.50, .30, .20, 1.);
        if(bx(u, -5., 5., -3., 5.)) c = vec4(.95, .75, .30, 1.);
        if(bx(u, -4., 8., -4., 8.)) c = vec4(.95, .75, .30, 1.);
    }

    float la = (enAir > .5 || fr == 0.) ? 3. : ((fr == 2.) ? -3. : 0.);
    float lb = -la;
    float jambeY0 = (enAir > .5) ? 1. : 0.;
    vec3 botte = vec3(.42, .26, .16);
    vec3 pantalon  = vec3(.22, .28, .50);
    if(bx(l, lb-1., jambeY0, lb, jambeY0+3.)) c = vec4((l.y - jambeY0 < 2.) ? botte*.8 : pantalon*.8, 1.);
    if(bx(l, la-1., jambeY0, la, jambeY0+3.)) c = vec4((l.y - jambeY0 < 2.) ? botte : pantalon, 1.);

    if(bx(u, -3., 4., 3., 8.)){
        vec3 tn = vec3(.20, .38, .80)*(.85 + .3*step(0., u.x));
        if(abs(u.y - 5.) < .5) tn = vec3(.62, .42, .16);
        if(abs(u.y - 5.) < .5 && abs(u.x) < .5) tn = vec3(.95, .80, .30);
        c = vec4(tn, 1.);
    }

    if(bx(u, -3., 8., 5., 11.)){
        vec3 hd = vec3(.97, .90, .78);
        if(abs(u.y - 8.) < .5) hd = vec3(.82, .72, .60);
        c = vec4(hd, 1.);
    }
    if(clin < .5){
        if(bx(u, 0., 9., 1., 11.) || bx(u, 3., 9., 4., 11.)) c = vec4(.08, .05, .12, 1.);
        if(bx(u, 0., 11., 0., 11.) || bx(u, 3., 11., 3., 11.)) c = vec4(1.);
    } else {
        if(bx(u, 0., 9., 1., 9.) || bx(u, 3., 9., 4., 9.)) c = vec4(.08, .05, .12, 1.);
    }
    if(bx(u, -1., 9., -1., 9.) || bx(u, 5., 9., 5., 9.)) c = vec4(1., .60, .65, 1.);
    if(bx(u, 2., 8., 2., 8.)) c = vec4(.60, .25, .30, 1.);

    if(gardeVisible > .5){
        if(bx(u, 3., 5., 5., 6.)) c = vec4(.70, .50, .30, 1.);
    }

    vec2 cq = (u - vec2(0., 17.))/vec2(8.6, 5.6);
    if(dot(cq, cq) < 1. && u.y >= 12.){
        vec3 cp = mix(vec3(.55, .08, .25), vec3(.95, .30, .45), clamp((u.y - 12.)/10., 0., 1.));
        if(u.y < 13.) cp = vec3(.40, .06, .20);
        vec2 s1 = u - vec2(-4., 19.);
        vec2 s2 = u - vec2(3., 20.);
        vec2 s3 = u - vec2(0., 15.);
        vec2 s4 = u - vec2(6., 16.);
        if(dot(s1,s1) < 3.2 || dot(s2,s2) < 2.6 || dot(s3,s3) < 1.5 || dot(s4,s4) < 1.1) cp = vec3(.99, .95, .85);
        c = vec4(cp, 1.);
    }

    if(gardeVisible < .5){
        float pp = sp;
        vec2 poigne = vec2(5.5, 7.5);
        float angle = radians(35.);
        if(st < 1.5){
            poigne = mix(vec2(-4., 7.), vec2(5.5, 7.5), pp) + vec2(0., 6.*sin(pp*3.14159));
            angle = mix(radians(210.), radians(35.), pp);
        } else if(st < 2.5){
            angle = radians(35.);
        } else if(st < 3.5){
            float a1 = radians(35.);
            float a2 = radians(115.);
            float a3 = radians(-45.);
            angle = (sp < .3) ? mix(a1, a2, sp/.3) : mix(a2, a3, smoothstep(0., 1., (sp - .3)/.7));
        } else if(st < 4.5){
            angle = mix(radians(-45.), radians(35.), smoothstep(0., 1., sp));
        } else {
            pp = 1. - sp;
            poigne = mix(vec2(-4., 7.), vec2(5.5, 7.5), pp) + vec2(0., 6.*sin(pp*3.14159));
            angle = mix(radians(210.), radians(35.), pp);
        }
        vec2 direction = vec2(cos(angle), sin(angle));
        vec2 perpendiculaire = vec2(-direction.y, direction.x);
        if(distSegment(u, vec2(3., 7.), poigne) < .8) c = vec4(.80, .70, .58, 1.);
        if(distSegment(u, poigne - direction*2., poigne) < .6) c = vec4(.45, .28, .18, 1.);
        if(length(u - (poigne - direction*2.5)) < .8) c = vec4(.95, .75, .30, 1.);
        if(distSegment(u, poigne + direction*.8 - perpendiculaire*2.2, poigne + direction*.8 + perpendiculaire*2.2) < .6) c = vec4(.95, .75, .30, 1.);
        float db = distSegment(u, poigne + direction*1.5, poigne + direction*9.5);
        if(db < .75) c = vec4(mix(vec3(.62, .70, .88), vec3(.95, .97, 1.), step(db, .35)), 1.);
        if(length(u - (poigne + direction*9.5)) < 1.) c = vec4(1.);
    }
    return c;
}

vec4 cheminHeros(float t){
  if(t < T0) return vec4(X0, niv0(X0), 0.0, 1.0);
  if(t < TA1){ float x = X0 + VMARCHE * (t - T0); return vec4(x, niv0(x), 0.0, 1.0); }
  if(t < TA2){ float u = (t - TA1) / (TA2 - TA1); return vec4(XL1, mix(niv0(XL1), niv1(XL1), u), 1.0, 1.0); }
  if(t < TB1){ float x = XL1 - VMARCHE * (t - TA2); return vec4(x, niv1(x), 0.0, -1.0); }
  if(t < TB2){ float u = (t - TB1) / (TB2 - TB1); return vec4(XL2, mix(niv1(XL2), niv2(XL2), u), 1.0, -1.0); }
  if(t < TC1){ float x = XL2 + VMARCHE * (t - TB2); return vec4(x, niv2(x), 0.0, 1.0); }
  if(t < TC2){ float u = (t - TC1) / (TC2 - TC1); return vec4(XL3, mix(niv2(XL3), niv4(XL3), u), 1.0, 1.0); }
  if(t < DEBUT_VICTOIRE){ float x = XL3 - VMARCHE * (t - TC2); return vec4(x, niv4(x), 0.0, -1.0); }
  return vec4(XFIN, niv4(XFIN), 2.0, -1.0);
}

vec4 positionTonneau(float age){
  float x;
  float y;
  float sens;
  if(age < T1){ x = XLANCER + VROULE * age; y = niv3(x) + 5.0; sens = -1.0; }
  else if(age < T2){ float u = (age - T1) / 0.5; x = XD; y = mix(niv3(x), niv2(x), u * u) + 5.0; sens = 1.0; }
  else if(age < T3){ x = XD - VROULE * (age - T2); y = niv2(x) + 5.0; sens = 1.0; }
  else if(age < T4){ float u = (age - T3) / 0.5; x = XG; y = mix(niv2(x), niv1(x), u * u) + 5.0; sens = -1.0; }
  else if(age < T5){ x = XG + VROULE * (age - T4); y = niv1(x) + 5.0; sens = -1.0; }
  else if(age < T6){ float u = (age - T5) / 0.5; x = XD; y = mix(niv1(x), niv0(x), u * u) + 5.0; sens = 1.0; }
  else if(age < T7){ x = XD - VROULE * (age - T6); y = niv0(x) + 5.0; sens = 1.0; }
  else return vec4(0.0);
  return vec4(x, y, age * 9.0 * sens, 1.0);
}

void preparer(){
  gHeros = cheminHeros(gTt);
  gSaut = 0.0;
  gSt = 0.0;
  gSp = 0.0;
  gLance = 0.0;
  gSecousse = 0.0;
  for(int i = 0; i < NS; i++){
    float tau = (gTt - SAUTS[i]) / DUREE_SAUT + 0.5;
    if(tau > 0.0 && tau < 1.0) gSaut = max(gSaut, 4.0 * HAUT_SAUT * tau * (1.0 - tau));
  }
  for(int i = 0; i < NC; i++){
    float d = gTt - COUPS[i];
    if(d > -0.75 && d < 0.8){
      if(d < -0.35){ gSt = 1.0; gSp = (d + 0.75) / 0.4; }
      else if(d < -0.15){ gSt = 2.0; gSp = 0.0; }
      else if(d < 0.15){ gSt = 3.0; gSp = (d + 0.15) / 0.3; }
      else if(d < 0.45){ gSt = 4.0; gSp = (d - 0.15) / 0.3; }
      else { gSt = 5.0; gSp = (d - 0.45) / 0.35; }
    }
  }
  for(int k = 0; k < NB; k++){
    float age = mod(gTt - DEPARTS[k], PERIODE);
    if(age < 0.4) gLance = 1.0;
    vec4 pos = positionTonneau(age);
    float vivant = (pos.w > 0.5 && age < MORTS[k]) ? 1.0 : 0.0;
    gTonneau[k] = vec4(pos.xyz, vivant);
    float depuis = age - MORTS[k];
    if(depuis >= 0.0 && depuis < 0.8){
      vec4 pm = positionTonneau(MORTS[k]);
      gDebris[k] = vec4(depuis, pm.x, pm.y, 1.0);
      gSecousse = max(gSecousse, step(depuis, 0.22) * (1.0 - depuis / 0.22));
    } else {
      gDebris[k] = vec4(0.0);
    }
  }
}

vec3 fond(vec2 p){
  float h = p.y / RES.y;
  vec3 c = mix(vec3(0.16, 0.05, 0.22), vec3(0.01, 0.01, 0.06), pow(h, 0.6));
  float e = alea(dot(p, vec2(12.9898, 78.233)));
  if(e > 0.994 && p.y > 80.0){
    float eclat = 0.5 + 0.5 * sin(gTemps * 3.0 + e * 200.0);
    c += vec3(0.8, 0.85, 1.0) * eclat * 0.8;
  }
  float bloc = floor(p.x / 14.0);
  float ht = 20.0 + alea(bloc * 1.7) * 60.0;
  if(p.y < ht){
    c = vec3(0.035, 0.02, 0.07) * (0.8 + 0.4 * alea(bloc));
    vec2 w = vec2(mod(p.x, 14.0), mod(p.y, 7.0));
    bool colonne = (w.x >= 2.0 && w.x < 5.0) || (w.x >= 8.0 && w.x < 11.0);
    if(colonne && w.y >= 2.0 && w.y < 5.0 && p.y > 5.0 && p.y < ht - 2.0){
      float cle = alea(bloc * 31.0 + floor(p.x / 3.0) * 7.0 + floor(p.y / 7.0) * 13.0);
      float allume = step(0.68, cle) * (0.7 + 0.3 * sin(gTemps * 0.5 + cle * 40.0));
      c += vec3(1.0, 0.75, 0.35) * allume * 0.75;
    }
  }
  return c;
}

vec4 couleurPoutre(float x, float d){
  vec3 rose = vec3(0.93, 0.2, 0.45);
  if(d < 0.5) return vec4(1.0, 0.5, 0.7, 1.0);
  if(d > 4.5) return vec4(rose * 0.55, 1.0);
  if(d < 1.5 && mod(x, 8.0) < 1.0) return vec4(1.0, 0.85, 0.9, 1.0);
  float tri = abs(mod(x, 8.0) - 4.0);
  float dd = 1.0 + tri * 0.75;
  if(abs(d - dd) < 0.9) return vec4(rose * (1.0 - 0.08 * d), 1.0);
  return vec4(0.0);
}

vec3 couleurEchelle(vec2 p, float xl, float bas, float haut){
  float dx = abs(p.x - xl);
  if(dx > 3.0 || p.y < floor(bas) || p.y > haut - 6.0) return vec3(-1.0);
  if(dx > 2.5) return (p.x < xl) ? vec3(0.4, 1.0, 1.0) : vec3(0.05, 0.55, 0.65);
  if(mod(p.y, 4.0) < 1.0) return vec3(0.15, 0.9, 0.95);
  return vec3(-1.0);
}

vec4 pileTonneaux(vec2 p){
  vec2 r = p - vec2(8.0, niv3(8.0) + 1.0);
  if(r.x < 0.0 || r.x >= 20.0 || r.y < 0.0 || r.y >= 20.0) return vec4(0.0);
  vec2 c = vec2(mod(r.x, 11.0), mod(r.y, 10.0));
  if(c.x > 8.5) return vec4(0.0);
  float lum = 0.7 + 0.3 * sin(c.x / 8.0 * 3.14159);
  vec3 o = vec3(0.95, 0.55, 0.12) * lum;
  if(c.y < 1.0 || c.y >= 9.0 || c.x < 1.0 || c.x >= 8.0) o = vec3(0.55, 0.22, 0.05);
  if(c.y == 2.0 || c.y == 7.0) o = vec3(0.3, 0.3, 0.6) * lum;
  return vec4(o, 1.0);
}

vec4 bidon(vec2 p){
  vec2 r = p - vec2(14.0, floor(niv0(18.0)) + 1.0);
  if(r.x < 0.0 || r.x > 10.0 || r.y < 0.0) return vec4(0.0);
  if(r.y <= 11.0){
    float lum = 0.75 + 0.25 * sin(r.x / 10.0 * 3.14159);
    vec3 b = vec3(0.15, 0.25, 0.85) * lum;
    if(r.x == 1.0) b = vec3(0.4, 0.55, 1.0);
    if(r.x == 0.0 || r.x == 10.0) b = vec3(0.06, 0.1, 0.4);
    if(r.y == 2.0 || r.y == 9.0) b = vec3(0.45, 0.65, 1.0) * lum;
    return vec4(b, 1.0);
  }
  float f = r.y - 12.0;
  if(f < 7.0){
    float lm = 4.5 - f * 0.65 + sin(gTemps * 20.0 + f * 2.0) * 0.9;
    if(abs(r.x - 5.0) < lm) return vec4(f < 2.5 ? vec3(1.0, 0.9, 0.2) : vec3(1.0, 0.45, 0.05), 1.0);
  }
  return vec4(0.0);
}

vec4 singe(vec2 p){
  vec2 dp = p - SINGE;
  float tv = gTt - DEBUT_VICTOIRE;
  float chute = clamp(tv / 0.35, 0.0, 1.0);
  float angle = chute * 1.5708;
  float tremble = (tv > 0.5) ? sin(gTemps * 35.0) * 0.5 : 0.0;
  vec2 r = dp - vec2(0.0, -12.0 + 14.0 * chute + tremble);
  vec2 d = vec2(r.x * cos(angle) - r.y * sin(angle), r.x * sin(angle) + r.y * cos(angle)) + vec2(0.0, -12.0);
  bool pleure = tv > 0.3;
  float leve = gLance * ((tv > 0.0) ? 0.0 : 1.0);
  vec3 fourrure = vec3(0.15, 0.7, 0.8);
  vec3 ombre = vec3(0.08, 0.42, 0.58);
  vec3 peau = vec3(1.0, 0.82, 0.65);
  vec3 c = vec3(0.0);
  float a = 0.0;

  vec2 f1 = d - vec2(-7.0, -10.5);
  vec2 f2 = d - vec2(7.0, -10.5);
  if(f1.x * f1.x / 16.0 + f1.y * f1.y / 2.5 < 1.0 || f2.x * f2.x / 16.0 + f2.y * f2.y / 2.5 < 1.0){ c = ombre; a = 1.0; }

  float e = d.x * d.x / 196.0 + d.y * d.y / 144.0;
  if(e < 1.0){
    float lum = clamp(1.0 - 0.15 * d.x / 14.0 + 0.2 * d.y / 12.0, 0.75, 1.25);
    c = fourrure * lum;
    if(e > 0.74) c = ombre * lum;
    a = 1.0;
  }

  vec2 vt = d - vec2(0.0, -4.0);
  if(vt.x * vt.x / 49.0 + vt.y * vt.y / 30.0 < 1.0){ c = peau * 0.95; a = 1.0; }

  float tape = step(0.5, fract(gTemps * 3.0));
  vec2 mainD = mix(vec2(17.0, -5.0), vec2(5.0, -2.0), tape);
  if(leve > 0.5) mainD = vec2(17.0, 14.0);
  vec2 mainG = vec2(-17.0, -3.0);
  if(tv > 0.0){
    mainD = vec2(4.0, 9.0 + sin(gTemps * 25.0));
    mainG = vec2(-17.0, 2.0 + 5.0 * sin(gTemps * 14.0));
  }
  if(distSegment(d, vec2(11.0, 2.0), mainD) < 2.6 || distSegment(d, vec2(-11.0, 2.0), mainG) < 2.6){ c = fourrure * 0.85; a = 1.0; }
  if(length(d - mainD) < 3.0 || length(d - mainG) < 3.0){ c = vec3(0.95, 0.7, 0.55); a = 1.0; }

  vec2 tete = d - vec2(0.0, 9.0);
  if(dot(tete, tete) < 72.0){
    c = fourrure * clamp(1.0 + 0.2 * tete.y / 8.5 - 0.1 * tete.x / 8.5, 0.8, 1.2);
    a = 1.0;
  }

  for(int i = 0; i < 2; i++){
    float s = (i == 0) ? -1.0 : 1.0;
    vec2 oreille = d - vec2(9.5 * s, 10.0);
    if(dot(oreille, oreille) < 12.0){
      c = ombre;
      if(dot(oreille, oreille) < 4.0) c = vec3(1.0, 0.6, 0.65);
      a = 1.0;
    }
  }

  vec2 fc = d - vec2(0.0, 7.5);
  if(fc.x * fc.x / 49.0 + fc.y * fc.y / 36.0 < 1.0){ c = peau; a = 1.0; }

  for(int i = 0; i < 2; i++){
    float s = (i == 0) ? -1.0 : 1.0;
    vec2 joue = d - vec2(5.5 * s, 5.0);
    if(dot(joue, joue) < 1.8){ c = vec3(1.0, 0.55, 0.6); a = 1.0; }
    vec2 oeil = d - vec2(3.0 * s, 11.0);
    if(dot(oeil, oeil) < 7.0){
      if(pleure){
        if(abs(oeil.y + 0.2) < 0.8){ c = vec3(0.05, 0.02, 0.08); a = 1.0; }
      } else {
        c = vec3(1.0);
        a = 1.0;
        vec2 pu = oeil - vec2(-1.2 * s, sin(gTemps * 4.0 + s) * 0.7);
        if(dot(pu, pu) < 1.6) c = vec3(0.05, 0.02, 0.08);
      }
    }
  }

  float ouv = pleure ? 2.6 + 0.5 * sin(gTemps * 20.0) : 1.6 + 0.6 * sin(gTemps * 8.0);
  vec2 bouche = d - vec2(0.0, 5.0);
  if(bouche.x * bouche.x / 20.0 + bouche.y * bouche.y / (ouv * ouv) < 1.0){
    c = vec3(0.12, 0.0, 0.06);
    a = 1.0;
    if(bouche.y > ouv * 0.45 && !pleure) c = vec3(1.0);
  }
  vec2 langue = d - vec2(1.5, 3.4);
  if(langue.x * langue.x / 5.0 + langue.y * langue.y / 2.6 < 1.0 && d.y < 4.5 && !pleure){ c = vec3(0.95, 0.25, 0.35); a = 1.0; }

  for(int i = -1; i <= 1; i++){
    float tx = d.x - 2.5 * float(i);
    if(abs(tx) < 0.7 && d.y >= 16.0 && d.y <= 19.5 - 1.5 * abs(float(i))){ c = ombre; a = 1.0; }
  }

  vec2 bn = d - (mainG + vec2(-1.0, 4.0));
  float rb = length(bn - vec2(2.0, 0.0));
  if(rb > 3.0 && rb < 4.6 && bn.x < 1.0 && bn.y > -3.0 && bn.y < 4.0 && leve < 0.5 && tv <= 0.0){
    c = (bn.y > 3.0) ? vec3(0.4, 0.25, 0.1) : vec3(1.0, 0.9, 0.2);
    a = 1.0;
  }

  if(tv > 0.3){
    vec2 oeilHaut = vec2(23.0, 5.0);
    for(int i = 0; i < 6; i++){
      float ti = fract(gTemps * 1.7 + float(i) / 6.0);
      vec2 tp = oeilHaut + vec2(3.0 + alea(float(i)) * 9.0, 8.0) * ti + vec2(0.0, -34.0 * ti * ti);
      if(abs(dp.x - tp.x) < 1.0 && abs(dp.y - tp.y) < 1.0 && tp.y > -12.0){ c = vec3(0.45, 0.75, 1.0); a = 1.0; }
    }
    float flaque = min(2.0 + (tv - 0.3) * 3.0, 13.0);
    if(dp.y >= -12.0 && dp.y < -10.0 && abs(dp.x - 33.0) < flaque - (dp.y + 12.0) * 1.5){ c = vec3(0.35, 0.65, 1.0); a = 1.0; }
  }

  return vec4(c, a);
}

float formeCoeur(vec2 u){
  float a = u.x * u.x + u.y * u.y - 1.0;
  return a * a * a - u.x * u.x * u.y * u.y * u.y;
}

vec3 scene(vec2 p){
  vec3 c = fond(p);

  vec3 lc;
  lc = couleurEchelle(p, XL1, niv0(XL1), niv1(XL1)); if(lc.x >= 0.0) c = lc;
  lc = couleurEchelle(p, XL2, niv1(XL2), niv2(XL2)); if(lc.x >= 0.0) c = lc;
  lc = couleurEchelle(p, XL3, niv2(XL3), niv4(XL3)); if(lc.x >= 0.0) c = lc;
  lc = couleurEchelle(p, 170.0, niv0(170.0), 0.5 * (niv0(170.0) + niv1(170.0)) + 6.0); if(lc.x >= 0.0) c = lc;
  lc = couleurEchelle(p, 250.0, niv1(250.0), 0.5 * (niv1(250.0) + niv2(250.0)) + 6.0); if(lc.x >= 0.0) c = lc;
  lc = couleurEchelle(p, 130.0, niv2(130.0), 0.5 * (niv2(130.0) + niv3(130.0)) + 6.0); if(lc.x >= 0.0) c = lc;
  lc = couleurEchelle(p, 210.0, niv0(210.0), 0.5 * (niv0(210.0) + niv1(210.0)) + 6.0); if(lc.x >= 0.0) c = lc;

  float ys[5];
  ys[0] = floor(niv0(p.x));
  ys[1] = floor(niv1(p.x));
  ys[2] = floor(niv2(p.x));
  ys[3] = floor(niv3(p.x));
  ys[4] = floor(niv4(p.x));
  for(int i = 0; i < 5; i++){
    bool dedans = (i < 4) ? (p.x >= 12.0 && p.x < 388.0) : (p.x >= 252.0 && p.x < 356.0);
    float d = ys[i] - p.y;
    if(dedans && d >= 0.0 && d < 6.0){
      vec4 q = couleurPoutre(p.x, d);
      if(q.a > 0.5) c = q.rgb;
    }
  }
  if((abs(p.x - 256.0) < 1.5 || abs(p.x - 352.0) < 1.5) && p.y > ys[3] && p.y < ys[4] - 5.0) c = vec3(0.55, 0.12, 0.28);

  float dfl = length(p - vec2(19.0, 26.0));
  c += vec3(1.0, 0.5, 0.1) * 0.55 * exp(-dfl * dfl / 220.0) * (0.8 + 0.2 * sin(gTemps * 25.0));
  vec2 chc = vec2(XCOEUR, niv4(XCOEUR) + 9.0);
  float dcc = length(p - chc);
  c += vec3(1.0, 0.2, 0.4) * 0.3 * exp(-dcc * dcc / 90.0);

  vec4 pile = pileTonneaux(p);
  if(pile.a > 0.5) c = pile.rgb;
  vec2 dm = p - SINGE;
  if(dm.x > -30.0 && dm.x < 55.0 && dm.y > -16.0 && dm.y < 38.0){
    vec4 mo = singe(p);
    if(mo.a > 0.5) c = mo.rgb;
  }

  float pouls = 1.0 + 0.1 * sin(gTemps * 8.0);
  if(gTt > DEBUT_VICTOIRE) pouls = 1.0 + 0.2 * sin(gTemps * 12.0);
  vec2 hc = vec2(XCOEUR, niv4(XCOEUR) + 9.0 + sin(gTemps * 3.0) * 1.5);
  vec2 hu = (p - hc) / (4.5 * pouls);
  if(formeCoeur(hu) < 0.0){
    c = vec3(1.0, 0.25, 0.45) * (0.85 + 0.3 * clamp(-hu.x * 0.5 + hu.y * 0.5, 0.0, 1.0));
    if(p.x == floor(hc.x - 2.0) && p.y == floor(hc.y + 2.0)) c = vec3(1.0, 0.8, 0.9);
  }

  for(int k = 0; k < NB; k++){
    vec4 b = gTonneau[k];
    if(b.w > 0.5){
      vec2 d = p - vec2(floor(b.x + 0.5), floor(b.y + 0.5));
      float r = length(d);
      if(r <= 4.6){
        float l = 0.65 + 0.45 * clamp(dot(d / max(r, 0.001), vec2(-0.6, 0.8)) * (r / 4.6) + 0.2, 0.0, 1.0);
        vec3 bois = vec3(0.95, 0.55, 0.12);
        if(r > 3.7) bois = vec3(0.55, 0.22, 0.06);
        float an = b.z;
        float cerceau = abs(dot(d, vec2(-sin(an), cos(an))));
        if(cerceau < 0.8) bois = vec3(0.35, 0.35, 0.55);
        c = bois * l;
        if(r > 4.0) c = vec3(0.15, 0.06, 0.02);
      }
    }
  }

  vec4 bi = bidon(p);
  if(bi.a > 0.5) c = bi.rgb;

  for(int k = 0; k < NB; k++){
    vec4 db = gDebris[k];
    if(db.w > 0.5){
      float t = db.x;
      if(t < 0.12){
        float r = length(p - db.yz);
        float rayon = 8.0 * (1.0 - t / 0.12);
        if(r < rayon) c += vec3(1.0, 0.9, 0.5) * (1.0 - r / rayon) * 0.9;
      }
      for(int i = 0; i < 7; i++){
        float an = 0.35 + float(i) * 0.45;
        float vit = 26.0 + alea(float(i) + 3.0) * 16.0;
        vec2 pos = db.yz + vec2(cos(an), sin(an)) * vit * t + vec2(0.0, -110.0 * t * t);
        if(abs(p.x - pos.x) < 1.6 && abs(p.y - pos.y) < 1.2 && t < 0.75){
          c = (i % 2 == 0) ? vec3(0.95, 0.55, 0.12) : vec3(0.55, 0.25, 0.08);
        }
      }
    }
  }

  float etat = gHeros.z;
  float saut = gSaut;
  if(etat > 1.5) saut = 6.0 * abs(sin((gTt - DEBUT_VICTOIRE) * 5.0));
  if(etat > 0.5 && etat < 1.5) saut = 0.0;
  vec2 hpos = vec2(floor(gHeros.x + 0.5), floor(gHeros.y) + 1.0 + floor(saut + 0.5));
  vec2 q = p - hpos;
  float marche = (etat < 0.5 && gTt > T0) ? 1.0 : 0.0;
  float fr = floor(mod(gTemps * 10.0, 4.0)) * marche;
  float st = (etat < 1.5) ? gSt : 2.0;
  float sp = (etat < 1.5) ? gSp : 0.0;
  float air = (saut > 0.5) ? 1.0 : 0.0;
  float sens = gHeros.w;
  if(etat > 0.5 && etat < 1.5){
    float alterne = (mod(floor(gTemps * 5.0), 2.0) < 0.5) ? 1.0 : -1.0;
    sens = alterne;
    fr = (alterne > 0.0) ? 0.0 : 2.0;
  }
  q.x *= sens;
  float clin = step(mod(gTemps, 2.8), 0.12);
  if(q.x > -14.0 && q.x < 18.0 && q.y > -2.0 && q.y < 27.0){
    vec4 h = pixelHeros(q, fr, air, st, sp, clin);
    if(h.a > 0.5) c = h.rgb;
  }

  float tv = gTt - DEBUT_VICTOIRE;
  if(tv > 0.0){
    float tl = mod(tv, 1.0);
    float id = floor(tv);
    for(int i = 0; i < 20; i++){
      float an = float(i) * 0.314 + alea(float(i) + id) * 0.6;
      float vit = 18.0 + alea(float(i) + 7.0 + id) * 26.0;
      vec2 pos = vec2(XCOEUR + 14.0, niv4(XCOEUR) + 30.0) + vec2(cos(an), sin(an)) * vit * tl + vec2(0.0, -30.0 * tl * tl);
      if(tl < 0.9 && abs(p.x - pos.x) < 1.2 && abs(p.y - pos.y) < 1.2){
        c = 0.6 + 0.4 * vec3(alea(float(i) + id * 3.0), alea(float(i) * 2.0 + 1.0), alea(float(i) * 5.0 + 2.0));
      }
    }
  }

  for(int i = 0; i < 2; i++){
    vec2 r = p - vec2(14.0 + 10.0 * float(i), 205.0);
    if(r.y >= 2.0 && r.y <= 5.0 && r.x >= -4.0 && r.x <= 4.0){
      float e = r.x * r.x / 20.0 + (r.y - 2.0) * (r.y - 2.0) / 9.0;
      if(e < 1.0){ c = vec3(1.0, 0.45, 0.6); if(r.x == -1.0 && r.y == 4.0) c = vec3(1.0); }
    }
    if(r.y >= 0.0 && r.y <= 1.0 && abs(r.x) <= 2.0) c = (r.y == 1.0) ? vec3(1.0, 0.85, 0.7) : vec3(0.25, 0.4, 0.95);
  }

  return c;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord){
  gTemps = iTime;
  gTt = mod(iTime, PERIODE);
  preparer();

  float s = min(iResolution.x / RES.x, iResolution.y / RES.y);
  vec2 v = (fragCoord - 0.5 * iResolution.xy) / s + RES * 0.5;
  vec2 n = v / RES * 2.0 - 1.0;
  if(abs(n.x) > 1.0 || abs(n.y) > 1.0){ fragColor = vec4(0.0, 0.0, 0.0, 1.0); return; }
  vec2 n2 = n * vec2(1.0 + 0.02 * n.y * n.y, 1.0 + 0.035 * n.x * n.x);
  if(abs(n2.x) > 1.0 || abs(n2.y) > 1.0){ fragColor = vec4(0.0, 0.0, 0.0, 1.0); return; }
  vec2 v2 = (n2 * 0.5 + 0.5) * RES;
  v2 += vec2(sin(iTime * 95.0), cos(iTime * 83.0)) * gSecousse * 1.5;
  vec2 p = floor(v2);
  vec2 f = fract(v2);

  vec3 col = scene(p);

  float ligne = 0.72 + 0.28 * sin(3.14159 * f.y);
  float grille = 0.92 + 0.08 * sin(3.14159 * f.x);
  col *= ligne * grille;
  col *= 1.0 + 0.04 * sin(v2.y * 0.05 - iTime * 2.0);
  col *= 0.97 + 0.03 * sin(iTime * 60.0);
  col += (alea(dot(fragCoord, vec2(1.0, 57.0)) + iTime) - 0.5) * 0.03;

  float bord = 1.0 - smoothstep(0.94, 1.0, max(abs(n2.x), abs(n2.y)));
  col *= bord;
  col *= 1.0 - 0.3 * dot(n, n);

  float fondu = min(smoothstep(0.0, 0.5, gTt), 1.0 - smoothstep(PERIODE - 0.5, PERIODE, gTt));
  col *= fondu;

  col *= 1.15;
  col = pow(max(col, 0.0), vec3(0.92));
  fragColor = vec4(col, 1.0);
}

const float PERIODE = 33.1797;
const float AVANCE = 0.15;
const float VMARCHE = 48.0;
const float VROULE = 56.0;
const float XD = 384.0;
const float XG = 16.0;
const float XLANCER = 74.0;
const float XGOUFFRE = 28.0;
const float T1 = (XD - XLANCER) / VROULE;
const float T2 = T1 + 0.5;
const float T3 = T2 + (XD - XG) / VROULE;
const float T4 = T3 + 0.5;
const float T5 = T4 + (XD - XG) / VROULE;
const float T6 = T5 + 0.5;
const float T7 = T6 + (XD - XGOUFFRE) / VROULE;
const float T0 = 0.8;
const float TA1 = 7.0083;
const float TA2 = 8.6465;
const float TB1 = 14.7298;
const float TB2 = 16.6043;
const float TC1 = 22.4793;
const float TC2 = 25.7630;
const float DEBUT_VICTOIRE = 26.6797;
const float DUREE_SAUT = 0.55;
const int NB = 6;
const int NS = 4;
const int NC = 3;
const float DEPARTS[NB] = float[NB](2.4500, 6.9500, 10.4500, 13.9500, 17.9500, 23.7000);
const float MORTS[NB] = float[NB](99.0000, 10.7220, 24.7977, 99.0000, 21.3377, 99.0000);
const float SAUTS[NS] = float[NS](4.0760, 9.1560, 19.6760, 21.5600);
const float COUPS[NC] = float[NC](1.9680, 6.0080, 17.5720);

const float TAU = 6.2831853;

float alea(float n){ return fract(sin(n * 91.3458) * 47453.5453); }
float bruit(float t, float rate, float seed){ return alea(floor(t * rate) + seed) * 2.0 - 1.0; }
float carre(float f, float t){ return (fract(f * t) < 0.5) ? 1.0 : -1.0; }
float pulse(float f, float t, float w){ return (fract(f * t) < w) ? 1.0 : -1.0; }
float tri(float f, float t){ return abs(fract(f * t) * 4.0 - 2.0) - 1.0; }
float midi(float n){ return 440.0 * exp2((n - 69.0) / 12.0); }

float dans(float dt, float d){ return (dt >= 0.0 && dt < d) ? 1.0 : 0.0; }

float sfxLancer(float dt){
  float w = dans(dt, 0.4);
  dt = max(dt, 0.0);
  float f = 110.0 - 140.0 * dt;
  float corps = sin(TAU * f * dt) * exp(-dt * 10.0);
  float choc = bruit(dt, 6000.0, 1.0) * exp(-dt * 40.0) * 0.5;
  return w * (corps * 0.9 + choc) * 0.6;
}

float sfxRoule(float t, float age){

  float rot = 0.6 + 0.4 * sin(TAU * 9.0 * age);
  float gr = bruit(t, 900.0, 5.0) * 0.5 + sin(TAU * 52.0 * t) * 0.5;
  return gr * rot * 0.12;
}

float sfxChute(float dt, float d){

  float w = dans(dt, d);
  float u = dt / d;
  float f = 900.0 - 650.0 * u;
  return w * carre(f, dt) * 0.07 * (1.0 - u * 0.5);
}

float sfxSaut(float dt){
  float w = dans(dt, DUREE_SAUT);
  float u = dt / DUREE_SAUT;
  float f = (u < 0.5) ? mix(260.0, 760.0, u * 2.0) : mix(760.0, 330.0, (u - 0.5) * 2.0);
  float ph = f * dt;
  return w * pulse(1.0, ph, 0.35) * 0.16 * (1.0 - u * 0.6);
}

float sfxMarteau(float t, float c){

  float swing = dans(t - (c - 0.35), 0.5);
  float u = clamp((t - (c - 0.35)) / 0.5, 0.0, 1.0);
  float whoosh = bruit(t, 5000.0, 9.0) * sin(3.14159 * u) * 0.22 * swing;
  float dt = t - (c + 0.15);
  float w = dans(dt, 0.35);
  dt = max(dt, 0.0);
  float coup = (bruit(dt, 9000.0, 2.0) * exp(-dt * 30.0) * 0.8
              + sin(TAU * (160.0 - 220.0 * dt) * dt) * exp(-dt * 14.0)) * w * 0.55;
  float ping = sin(TAU * 1250.0 * dt) * exp(-dt * 35.0) * w * 0.2;
  return whoosh + coup + ping;
}

float sfxExplo(float dt){
  float w = dans(dt, 0.8);
  dt = max(dt, 0.0);
  float env = exp(-dt * 6.0);
  float souffle = bruit(dt, 7000.0 * exp(-dt * 3.0) + 400.0, 4.0) * env;
  float basse = sin(TAU * (70.0 - 45.0 * dt) * dt) * exp(-dt * 7.0);
  return w * (souffle * 0.65 + basse * 0.8) * 0.7;
}

float sfxPas(float t){
  float c = fract(t * 5.0);
  return bruit(t, 12000.0, 3.0) * exp(-c * 45.0) * 0.08 + sin(TAU * 140.0 * c) * exp(-c * 30.0) * 0.05;
}

float sfxEchelle(float t){
  float c = fract(t * 8.0);
  float f = (mod(floor(t * 8.0), 2.0) < 0.5) ? 520.0 : 390.0;
  return carre(f, c) * exp(-c * 9.0) * 0.07;
}

float sfxVictoire(float tv){

  float s = 0.0;
  const float notes[8] = float[8](72., 76., 79., 84., 79., 84., 88., 91.);
  float idx = floor(tv / 0.14);
  if(idx < 8.0){
    float dt = tv - idx * 0.14;
    int i = int(idx);
    float f = midi(notes[i]);
    s += pulse(f, tv, 0.25) * exp(-dt * 6.0) * 0.18;
  } else if(tv < 1.6){
    float dt = tv - 8.0 * 0.14;
    float f = midi(91.0);
    s += (pulse(f, tv, 0.5) + 0.5 * carre(f * 2.0, tv)) * exp(-dt * 2.0) * 0.12;
  }

  float tp = tv - 0.35;
  if(tp > 0.0){
    float cy = mod(tp, 1.1);
    float fp = 420.0 - 160.0 * cy + 18.0 * sin(TAU * 7.0 * tp);
    float amp = sin(3.14159 * clamp(cy / 1.0, 0.0, 1.0));
    s += (tri(fp, tp) * 0.6 + carre(fp * 0.5, tp) * 0.2) * amp * 0.11;
  }
  return s;
}

const float BPM = 128.0;
const float PAS = 60.0 / BPM / 2.0;

float musique(float t, out float pan){
  float ph = t / PAS;
  float pas = floor(ph);
  float dt = (ph - pas) * PAS;
  float mesure = floor(pas / 8.0);
  float m = mod(mesure, 4.0);

  float racine = (m < 0.5) ? 45.0 : (m < 1.5) ? 41.0 : (m < 2.5) ? 48.0 : 43.0;
  float p8 = mod(pas, 8.0);

  float nb = racine + ((mod(p8, 2.0) < 0.5) ? 0.0 : 12.0);
  float basse = pulse(midi(nb), t, 0.5) * exp(-dt * 7.0) * 0.20;

  bool mineur = (m < 0.5);
  float arp[4] = float[4](0.0, 3.0, 7.0, 12.0);
  float arpM[4] = float[4](0.0, 4.0, 7.0, 12.0);
  int k = int(mod(pas, 4.0));
  float deg = mineur ? arp[k] : arpM[k];
  float nl = racine + 24.0 + deg;
  float lead = pulse(midi(nl), t, 0.25) * exp(-dt * 5.0) * 0.10;
  pan = (mod(pas, 2.0) < 0.5) ? -0.35 : 0.35;

  float tempsPas = mod(pas, 2.0);
  float kick = 0.0;
  if(tempsPas < 0.5){
    float kt = dt;
    kick = sin(TAU * (130.0 * exp(-kt * 28.0) + 45.0) * kt) * exp(-kt * 9.0) * 0.45;
  }
  float hat = 0.0;
  if(tempsPas > 0.5){
    hat = bruit(t, 14000.0, 7.0) * exp(-dt * 40.0) * 0.07;
  }
  float caisse = 0.0;
  if(mod(pas, 4.0) > 1.5 && mod(pas, 4.0) < 2.5){
    caisse = (bruit(t, 9000.0, 8.0) * 0.7 + sin(TAU * 190.0 * dt) * 0.3) * exp(-dt * 16.0) * 0.18;
  }
  return basse + lead + kick + hat + caisse;
}

vec2 mainSound(int samp, float time)
{
  float t = mod(time + AVANCE, PERIODE);
  float s = 0.0;
  vec2 st = vec2(0.0);

  float pan;
  float mus = musique(t, pan);
  float gm = (t < DEBUT_VICTOIRE) ? 1.0 : 0.25;
  vec2 musSt = vec2(mus) * gm;
  musSt *= vec2(1.0 - 0.4 * max(pan, 0.0), 1.0 + 0.4 * min(pan, 0.0));
  st += musSt;

  for(int k = 0; k < NB; k++){
    float age = mod(t - DEPARTS[k], PERIODE);
    s += sfxLancer(age);
    float finVie = min(T7, MORTS[k]);
    if(MORTS[k] < 90.0) s += sfxExplo(age - MORTS[k]);
  }

  for(int i = 0; i < NS; i++){
    s += sfxSaut(t - (SAUTS[i] - 0.5 * DUREE_SAUT));
  }

  for(int i = 0; i < NC; i++){
    s += sfxMarteau(t, COUPS[i]);
  }

  bool marche = (t > T0 && t < TA1) || (t > TA2 && t < TB1) || (t > TB2 && t < TC1) || (t > TC2 && t < DEBUT_VICTOIRE);
  bool echelle = (t > TA1 && t < TA2) || (t > TB1 && t < TB2) || (t > TC1 && t < TC2);
  if(marche) s += sfxPas(t);
  if(echelle) s += sfxEchelle(t);

  if(t > DEBUT_VICTOIRE) s += sfxVictoire(t - DEBUT_VICTOIRE);

  st += vec2(s);

  float fondu = min(smoothstep(0.0, 0.5, t), 1.0 - smoothstep(PERIODE - 0.5, PERIODE, t));
  st *= fondu;

  if(any(isnan(st)) || any(isinf(st))) st = vec2(0.0);
  return clamp(st, -1.0, 1.0);
}
